impl RefusalTemplate {
    pub fn to_json(&self) -> crate::kernel::Json {
        crate::kernel::Json::Object(vec![
            (
                "refusal".to_string(),
                crate::kernel::Json::Str(self.refusal.to_string()),
            ),
            (
                "site".to_string(),
                crate::kernel::Json::Str(self.site.to_string()),
            ),
            (
                "template".to_string(),
                crate::kernel::Json::Str(self.template.to_string()),
            ),
        ])
    }

    pub fn from_json(v: &crate::kernel::Json) -> Result<Self, crate::kernel::Refusal> {
        // `validate!`'s order: a name the set does not declare, then a field left out, then
        // membership of the whole row.
        let unknown = v.unknown_keys(&["refusal", "site", "template"]);
        if !unknown.is_empty() {
            let unknown: Vec<&str> = unknown.iter().map(String::as_str).collect();
            return Err(crate::kernel::Refusal::UnknownArgument(
                crate::kernel::refusal_wording::UnknownArgumentUnknownArgsArgs {
                    command: "RefusalTemplate",
                    unknown: &unknown,
                    declared: &["refusal", "site", "template"],
                }
                .render_args(),
            ));
        }
        if matches!(v.get("refusal"), None | Some(crate::kernel::Json::Null)) {
            return Err(crate::kernel::Refusal::TypeMismatch(
                "RefusalTemplate.refusal expects String, got nil".to_string(),
            ));
        }
        if matches!(v.get("site"), None | Some(crate::kernel::Json::Null)) {
            return Err(crate::kernel::Refusal::TypeMismatch(
                "RefusalTemplate.site expects String, got nil".to_string(),
            ));
        }
        if matches!(v.get("template"), None | Some(crate::kernel::Json::Null)) {
            return Err(crate::kernel::Refusal::TypeMismatch(
                "RefusalTemplate.template expects String, got nil".to_string(),
            ));
        }
        for row in REFUSAL_TEMPLATE {
            if v.get("refusal").and_then(crate::kernel::Json::as_str) == Some(row.refusal)
                && v.get("site").and_then(crate::kernel::Json::as_str) == Some(row.site)
                && v.get("template").and_then(crate::kernel::Json::as_str) == Some(row.template)
            {
                return Ok(row.clone());
            }
        }
        // The refusal quotes the first column only, as Ruby's `refuse_non_member!` does.
        let offered = v
            .get("refusal")
            .map(|offered| offered.inspect())
            .unwrap_or_else(|| "nil".to_string());
        Err(crate::kernel::Refusal::InvariantViolation(
            crate::kernel::refusal_wording::InvariantViolationClosedSetMemberArgs {
                r#type: "RefusalTemplate",
                admitted: &[
                    "NotFound",
                    "AlreadyExists",
                    "AlreadyExists",
                    "NotFound",
                    "NotFound",
                    "NotFound",
                    "UnknownVerb",
                    "NotFound",
                    "NotFound",
                    "NotFound",
                    "NotFound",
                    "TypeMismatch",
                    "UnknownVerb",
                    "UnknownVerb",
                    "UnknownVerb",
                    "UnknownVerb",
                    "UnknownVerb",
                    "UnknownVerb",
                    "UnknownVerb",
                    "UnknownVerb",
                    "UnknownVerb",
                    "UnknownVerb",
                    "LifecycleRefused",
                    "TypeMismatch",
                    "TypeMismatch",
                    "TypeMismatch",
                    "TypeMismatch",
                    "TypeMismatch",
                    "TypeMismatch",
                    "TypeMismatch",
                    "TypeMismatch",
                    "TypeMismatch",
                    "TypeMismatch",
                    "TypeMismatch",
                    "UnknownArgument",
                    "AbsentArgument",
                    "InvariantViolation",
                    "InvariantViolation",
                    "InvariantViolation",
                    "InvariantViolation",
                    "InvariantViolation",
                    "Unauthorized",
                    "Unauthorized",
                    "Unauthorized",
                    "AttributeAbsent",
                    "ProjectionAbsent",
                ],
                offered: offered.as_str(),
            }
            .render_args(),
        ))
    }
}

