                && v.get("shape").and_then(crate::kernel::Json::as_str) == Some(row.shape)
                && v.get("quoting").and_then(crate::kernel::Json::as_str) == Some(row.quoting)
                && v.get("separator").and_then(crate::kernel::Json::as_str) == Some(row.separator)
                && v.get("sorted").and_then(crate::kernel::Json::as_str) == Some(row.sorted)
